// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, "", ""); }
    function testFuzz_property(uint256 initialSupply, uint256 burnAmount) public {
        // Setup: create contract with a non-zero initial supply so burn can succeed
        c = new C(initialSupply, "", "");
        uint256 supplyBefore = c.totalSupply();

        // Call burn - it may revert if burnAmount > balanceOf[owner]
        (bool success, bytes memory data) = address(c).call(abi.encodeWithSignature("burn(uint256)", burnAmount));

        if (success) {
            // If successful, the return value must be true (from abi decode)
            bool returnValue = abi.decode(data, (bool));
            assertTrue(returnValue, "burn should return true on success");
            // Also verify totalSupply decreased exactly by burnAmount
            uint256 supplyAfter = c.totalSupply();
            assertTrue(supplyAfter == supplyBefore - burnAmount, "totalSupply should decrease by burnAmount");
        }
    }
}

